/** Guarded Episode02 workflow repair. Dry-run by default. Run from the existing studio folder. */
import fs from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {gunzipSync} from 'node:zlib';
const root=process.cwd(),out='out/v2-episodes/in-this-town-02/';
const hash=s=>createHash('sha256').update(s.replaceAll('\r\n','\n')).digest('hex');
const read=async name=>fs.readFile(path.resolve(root,name)).catch(e=>{if(e.code==='ENOENT')return null;throw e;});
const data=JSON.parse(gunzipSync(Buffer.from('','base64')));
const originals=new Map(),writes=new Map(),mismatches=[],preservedNotes=[];
for(const [name,expected] of Object.entries(data.guards)){const raw=await read(name);if(!raw||hash(raw.toString('utf8'))!==expected)mismatches.push(name);}
for(const [name,item] of Object.entries(data.files)){
 const allowed=name.startsWith('scripts/')||name.startsWith('src/v2/episodes/in-this-town-02/')||['../AGENTS.md','../.agents/skills/in-this-town-production/SKILL.md','../ONE_PROMPT_IN_THIS_TOWN.md','../NEXT_EPISODE_ONE_PROMPT.md'].includes(name);
 if(!allowed||hash(item.text)!==item.after)throw Error('Invalid workflow payload');
 const raw=await read(name),actual=raw===null?null:hash(raw.toString('utf8'));
 if(actual===item.after)continue;
 if(!item.before.includes(actual)){if(item.optionalNote){preservedNotes.push(name);continue;}mismatches.push(name);continue;}
 originals.set(name,raw);writes.set(name,Buffer.from(item.text));
}
const packageRaw=await read('package.json');if(!packageRaw)throw Error('Run from the existing studio folder; package.json missing. No files changed.');
const pkg=JSON.parse(packageRaw.toString('utf8'));pkg.scripts??={};let packageChanged=false;
for(const [name,command] of Object.entries(data.aliases)){
 if(pkg.scripts[name]&&pkg.scripts[name]!==command&&pkg.scripts[name]!==data.aliasBefore?.[name])mismatches.push('package.json script '+name);
 else if(pkg.scripts[name]!==command){pkg.scripts[name]=command;packageChanged=true;}
}
if(packageChanged){originals.set('package.json',packageRaw);writes.set('package.json',Buffer.from(JSON.stringify(pkg,null,2)+'\n'));}
if(mismatches.length)throw Error('Different/newer local source: '+mismatches.join(', ')+'. No files changed. Reconcile these files; do not force-overwrite them.');
const propsRaw=await read(out+'render-props.json');if(!propsRaw)throw Error('Existing approved render-props.json missing. No files changed.');
const props=JSON.parse(propsRaw.toString('utf8'));
if(props.audioApproved!==true||props.shots?.length!==62||props.shots.at(-1)?.end!==3737)throw Error('Local approved edit differs from the reviewed 62-segment/3737-frame edit. No files changed.');
const legacyAudit=await read('scripts/episode02-action-evidence.mjs');
console.log(JSON.stringify({preservedLegacyAudit:legacyAudit?{file:'scripts/episode02-action-evidence.mjs',sha256:hash(legacyAudit.toString('utf8'))}:null,stage:'WORKFLOW_UPDATE_VERIFIED',files:[...writes.keys()],preservedNotes,rendering:false,audioChanged:false},null,2));
if(!process.argv.includes('--apply')){console.log('Dry run only. Add --apply to install with backups.');process.exit(0);}
if(!writes.size){console.log('Already installed. Next: npm.cmd run episode2:review -- --open');process.exit(0);}
const backup=path.join(root,out,'workflow-backup-'+Date.now());await fs.mkdir(backup,{recursive:true});
for(const [name,raw] of originals)if(raw!==null){const safeName=name.startsWith('../')?'repository/'+name.slice(3):'studio/'+name;const file=path.join(backup,safeName);await fs.mkdir(path.dirname(file),{recursive:true});await fs.writeFile(file,raw);}
await fs.writeFile(path.join(backup,'RESTORE_MANIFEST.json'),JSON.stringify({replaced:[...originals].filter(([,b])=>b!==null).map(([n])=>n),created:[...originals].filter(([,b])=>b===null).map(([n])=>n)},null,2)+'\n');
for(const [name,raw] of originals){const now=await read(name);if((raw===null)!==(now===null)||(raw&&now&&!raw.equals(now)))throw Error('Source changed during backup: '+name+'. No source written.');}
try{
 for(const [name,raw] of writes){const file=path.resolve(root,name);await fs.mkdir(path.dirname(file),{recursive:true});await fs.writeFile(file,raw);}
 for(const [name,raw] of writes)if(!(await read(name))?.equals(raw))throw Error('Write verification failed: '+name);
}catch(error){for(const [name,raw] of originals){if(raw===null)await fs.rm(path.resolve(root,name),{force:true});else await fs.writeFile(path.resolve(root,name),raw);}throw error;}
console.log('Installed with backups: '+backup+'\nNext: npm.cmd run episode2:review -- --open');
